import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_conv2d(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                           int64_t stride, int64_t padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define TILE 8
#define OC_TILE 4
#define RBW 2
__global__ void cute_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K, int stride, int padding,
    int H_out, int W_out,
    int TILE_H_IN, int TILE_W_IN,
    int OC_tiles)
{
    // Register-blocked over the output width dimension: each thread now
    // computes RBW (=2) output pixels that share the SAME staged input
    // tile and the SAME staged weight tile, doubling the useful work done
    // per shared-memory load and halving the number of CTAs launched along
    // the W_out dimension (less redundant weight/input staging overall).
    int n = blockIdx.z;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int ow0 = blockIdx.x * (TILE * RBW) + tx;
    int ow1 = ow0 + TILE;
    int oh = blockIdx.y * TILE + ty;
    const int wsize_per_oc = C_in * K * K;
    extern __shared__ float smem[];
    // shared memory layout: [ weights for current OC_TILE output channels | input tile (reused across oc tiles and both RBW columns) ]
    float* s_w0 = smem;
    float* s_w1 = smem + (size_t)OC_TILE * wsize_per_oc;
    float* s_in = smem + (size_t)2 * OC_TILE * wsize_per_oc;
    int tid = ty * TILE + tx;
    int nthreads = TILE * TILE;
    // stage the reusable input tile (with implicit zero padding) into shared memory
    // ONCE per block; this tile is shared across all OC_TILE output channels, all
    // output-channel tiles, and BOTH register-blocked output columns per thread.
    int ih_block_base = blockIdx.y * TILE * stride - padding;
    int iw_block_base = blockIdx.x * TILE * RBW * stride - padding;
    int hw_tile = TILE_H_IN * TILE_W_IN;
    int in_tile_size = C_in * hw_tile;
    const float* in_batch_ptr = input + (size_t)n * C_in * H_in * W_in;
    for (int i = tid; i < in_tile_size; i += nthreads) {
        int ic = i / hw_tile;
        int rem = i - ic * hw_tile;
        int local_h = rem / TILE_W_IN;
        int local_w = rem - local_h * TILE_W_IN;
        int ih = ih_block_base + local_h;
        int iw = iw_block_base + local_w;
        float val = 0.0f;
        if (ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
            val = in_batch_ptr[(size_t)ic * H_in * W_in + (size_t)ih * W_in + iw];
        }
        s_in[i] = val;
    }
    __syncthreads();
    bool active0 = (oh < H_out && ow0 < W_out);
    bool active1 = (oh < H_out && ow1 < W_out);
    int base_h = ty * stride;
    int base_w0 = tx * stride;
    int base_w1 = (tx + TILE) * stride;
    float* out_batch_ptr = output + (size_t)n * C_out * H_out * W_out;
    // Preload weights for the first output-channel tile into buffer 0.
    {
        int oc_base0 = 0;
        int oc_count0 = C_out;
        if (oc_count0 > OC_TILE) oc_count0 = OC_TILE;
        int wsize_total0 = oc_count0 * wsize_per_oc;
        for (int i = tid; i < wsize_total0; i += nthreads) {
            int oc_local = i / wsize_per_oc;
            int wi = i - oc_local * wsize_per_oc;
            const float* w_ptr = weight + (size_t)(oc_base0 + oc_local) * wsize_per_oc;
            s_w0[oc_local * wsize_per_oc + wi] = w_ptr[wi];
        }
    }
    __syncthreads();
    for (int oc_tile_idx = 0; oc_tile_idx < OC_tiles; ++oc_tile_idx) {
        float* cur_buf = (oc_tile_idx & 1) ? s_w1 : s_w0;
        float* nxt_buf = (oc_tile_idx & 1) ? s_w0 : s_w1;
        int oc_base = oc_tile_idx * OC_TILE;
        int oc_count = C_out - oc_base;
        if (oc_count > OC_TILE) oc_count = OC_TILE;
        // Prefetch weights for the NEXT output-channel tile into the other buffer.
        if (oc_tile_idx + 1 < OC_tiles) {
            int next_oc_base = (oc_tile_idx + 1) * OC_TILE;
            int next_oc_count = C_out - next_oc_base;
            if (next_oc_count > OC_TILE) next_oc_count = OC_TILE;
            int wsize_total_next = next_oc_count * wsize_per_oc;
            for (int i = tid; i < wsize_total_next; i += nthreads) {
                int oc_local = i / wsize_per_oc;
                int wi = i - oc_local * wsize_per_oc;
                const float* w_ptr = weight + (size_t)(next_oc_base + oc_local) * wsize_per_oc;
                nxt_buf[oc_local * wsize_per_oc + wi] = w_ptr[wi];
            }
        }
        if (active0 || active1) {
            float acc0[OC_TILE];
            float acc1[OC_TILE];
            #pragma unroll
            for (int t = 0; t < OC_TILE; ++t) {
                float bv = (t < oc_count) ? bias[oc_base + t] : 0.0f;
                acc0[t] = bv;
                acc1[t] = bv;
            }
            for (int ic = 0; ic < C_in; ++ic) {
                const float* s_in_ic = s_in + ic * hw_tile;
                #pragma unroll
                for (int kh = 0; kh < K; ++kh) {
                    const float* row = s_in_ic + (base_h + kh) * TILE_W_IN;
                    #pragma unroll
                    for (int kw = 0; kw < K; ++kw) {
                        float in_val0 = row[base_w0 + kw];
                        float in_val1 = row[base_w1 + kw];
                        #pragma unroll
                        for (int t = 0; t < OC_TILE; ++t) {
                            if (t < oc_count) {
                                const float* s_w_ic = cur_buf + t * wsize_per_oc + ic * K * K;
                                float wv = s_w_ic[kh * K + kw];
                                acc0[t] += in_val0 * wv;
                                acc1[t] += in_val1 * wv;
                            }
                        }
                    }
                }
            }
            #pragma unroll
            for (int t = 0; t < OC_TILE; ++t) {
                if (t < oc_count) {
                    if (active0) {
                        out_batch_ptr[(size_t)(oc_base + t) * H_out * W_out + (size_t)oh * W_out + ow0] = acc0[t];
                    }
                    if (active1) {
                        out_batch_ptr[(size_t)(oc_base + t) * H_out * W_out + (size_t)oh * W_out + ow1] = acc1[t];
                    }
                }
            }
        }
        // Single sync per iteration: ensures the prefetch into nxt_buf (used as
        // cur_buf next iteration) has completed, and that all reads of cur_buf
        // above have finished before it is reused as nxt_buf two iterations later.
        __syncthreads();
    }
}
torch::Tensor cute_conv2d(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                           int64_t stride, int64_t padding) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda() && bias.is_cuda(), "tensors must be CUDA");
    TORCH_CHECK(input.dim() == 4, "input must be 4D (N,C,H,W)");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D (C_out,C_in,K,K)");
    TORCH_CHECK(input.scalar_type() == at::kFloat, "expect float32");
    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();
    int N = (int)input_c.size(0);
    int C_in = (int)input_c.size(1);
    int H_in = (int)input_c.size(2);
    int W_in = (int)input_c.size(3);
    int C_out = (int)weight_c.size(0);
    int K = (int)weight_c.size(2);
    TORCH_CHECK(weight_c.size(1) == C_in, "channel mismatch");
    TORCH_CHECK(weight_c.size(3) == K, "kernel must be square");
    int H_out = (H_in + 2 * (int)padding - K) / (int)stride + 1;
    int W_out = (W_in + 2 * (int)padding - K) / (int)stride + 1;
    auto output = torch::empty({N, C_out, H_out, W_out}, input_c.options());
    dim3 block(TILE, TILE);
    int OC_tiles = (C_out + OC_TILE - 1) / OC_TILE;
    dim3 grid((W_out + TILE * RBW - 1) / (TILE * RBW),
              (H_out + TILE - 1) / TILE,
              N);
    int TILE_H_IN = (TILE - 1) * (int)stride + K;
    int TILE_W_IN = (TILE * RBW - 1) * (int)stride + K;
    size_t shmem = (size_t)2 * OC_TILE * C_in * K * K * sizeof(float) +
                   (size_t)C_in * TILE_H_IN * TILE_W_IN * sizeof(float);
    static bool attr_set = false;
    if (!attr_set) {
        cudaError_t attr_err = cudaFuncSetAttribute(cute_conv2d_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             (int)shmem);
        TORCH_CHECK(attr_err == cudaSuccess,
            "Requested dynamic shared memory (", shmem,
            " bytes) exceeds device capability: ", cudaGetErrorString(attr_err));
        attr_set = true;
    }
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_conv2d_kernel<<<grid, block, shmem, stream>>>(
        input_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        bias_c.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K, (int)stride, (int)padding,
        H_out, W_out,
        TILE_H_IN, TILE_W_IN,
        OC_tiles);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE conv2d launch failed");
    return output;
}
"""

cute_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv2d"],
    extra_cflags=["-O3", "-I/workspace/cutegen_test/cutegen/cutlass/include"],
    extra_cuda_cflags=["-O3", "-I/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.empty(96, 3, 11, 11))
        self.bias = nn.Parameter(torch.empty(96))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        fan_in = 3 * 11 * 11
        bound = 1.0 / (fan_in ** 0.5)
        nn.init.uniform_(self.bias, -bound, bound)
        self.stride = 4
        self.padding = 2
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        w = self.weight.to(x.device, dtype=x.dtype)
        b = self.bias.to(x.device, dtype=x.dtype)
        return self._ext.cute_conv2d(x, w, b, self.stride, self.padding)

